// Browser diagnostic of the actual production parser and presentation decoder.
// Input frames are generated by the real Native preview_transport_probe example.
import { parseNativePreviewFrame } from '../../src/nativeRender'
import { decodeNativePreviewPayload } from '../../src/nativePreviewPresentation'

export async function verifyNativePreviewTransport(prefix) {
  if (!/^preview-transport-\d+$/.test(prefix)) throw new Error('Invalid owned probe frame prefix')
  const results = {}
  const timings = { jpeg: [], rgba: [] }
  const canvases = {}
  for (const kind of ['jpeg', 'rgba']) {
    const response = await fetch(`/output/playwright/${prefix}-${kind}.bin`)
    if (!response.ok) throw new Error(`Missing Native probe frame: ${kind}`)
    results[kind] = parseNativePreviewFrame(await response.arrayBuffer())
    const canvas = document.createElement('canvas')
    canvas.width = results[kind].width
    canvas.height = results[kind].height
    canvas.setAttribute('aria-label', `Actual Native ${kind} preview`)
    canvas.style.maxWidth = '95vw'
    canvases[kind] = canvas
  }
  let rgbaByteDifferences = 0
  let releasedBitmaps = 0
  for (let round = 0; round < 22; ++round) {
    for (const kind of round % 2 ? ['rgba', 'jpeg'] : ['jpeg', 'rgba']) {
      const context = canvases[kind].getContext('2d', { willReadFrequently: true, colorSpace: 'srgb' })
      const start = performance.now()
      const presentation = await decodeNativePreviewPayload(results[kind])
      try {
        context.drawImage(presentation.image, 0, 0)
        const pixels = context.getImageData(0, 0, results[kind].width, results[kind].height).data
        if (round >= 2) timings[kind].push(performance.now() - start)
        if (kind === 'rgba') {
          for (let index = 0; index < pixels.length; ++index) {
            if (pixels[index] !== results[kind].payload.bytes[index]) ++rgbaByteDifferences
          }
        }
      } finally {
        presentation.release()
      }
      if (kind === 'rgba' && presentation.image.width === 0) ++releasedBitmaps
    }
  }
  if (rgbaByteDifferences !== 0 || releasedBitmaps !== 22) {
    throw new Error(`Presentation regression: ${rgbaByteDifferences} bytes; ${releasedBitmaps} releases`)
  }
  const stats = (samples) => {
    samples.sort((a, b) => a - b)
    return { medianMs: (samples[9] + samples[10]) / 2, p95Ms: samples[18], samplesMs: samples }
  }
  document.body.replaceChildren(...['jpeg', 'rgba'].flatMap((kind) => {
    const label = document.createElement('h2')
    label.textContent = kind === 'jpeg' ? '原生 JPEG 預覽（既有傳輸）' : '原生無損 RGBA8 預覽（新互動傳輸）'
    return [label, canvases[kind]]
  }))
  return { scope: 'Real Native frames + production parser/decoder + Chromium canvas; excludes Tauri IPC and OS presentation',
    width: results.rgba.width, height: results.rgba.height, measuredSamples: 20,
    rgbaByteDifferences, releasedBitmaps, jpeg: stats(timings.jpeg), rgba: stats(timings.rgba),
    userAgent: navigator.userAgent }
}
